def clean(df):
    category_mapping = {
        'furnture': 'Furniture',
        'accessories': 'Accessories',
    }
    df['Category'] = df['Category'].apply(lambda x: category_mapping.get(x.lower(), x))
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    df['Category'] = df['Category'].apply(lambda x: x if x in allowed else 'Invalid Category')
    return df

def answer(df):
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    category_counts = df['Category'].value_counts().to_dict()
    result = {k: v for k, v in category_counts.items() if k in allowed}
    return result
